import{_ as e,o as r,c as t,am as o}from"./chunks/framework._FJXuPhs.js";const c=JSON.parse('{"title":"Kafka 的重试机制","description":"","frontmatter":{"title":"Kafka 的重试机制","excerpt":"摘要","date":"2025-11-18 11:22:17","updated":"2025-11-18 11:22:17"},"headers":[],"relativePath":"中间件/中间件 - 消息队列/消息队列_Kafka/Kafka 的重试机制.md","filePath":"中间件/中间件 - 消息队列/消息队列_Kafka/Kafka 的重试机制.md","lastUpdated":null}'),n={name:"中间件/中间件 - 消息队列/消息队列_Kafka/Kafka 的重试机制.md"};function i(l,a,s,d,p,f){return r(),t("div",null,[...a[0]||(a[0]=[o('<h3 id="生产端的重试" tabindex="-1">生产端的重试 <a class="header-anchor" href="#生产端的重试" aria-label="Permalink to &quot;生产端的重试&quot;">​</a></h3><p>生产者在向Kafka发送消息时，可能会因为网络问题、Broker不可用、队列满等原因导致发送失败。Kafka生产者内置了重试机制，用于确保消息尽最大努力被成功发送到Kafka集群。</p><h3 id="消费端的重试" tabindex="-1">消费端的重试 <a class="header-anchor" href="#消费端的重试" aria-label="Permalink to &quot;消费端的重试&quot;">​</a></h3><p>在 Kafka 中，消费者从 <code>broker</code> 拉取消息并处理时，可能会因为处理逻辑失败而无法成功消费消息。Kafka的消费者端重试机制并不是自动化内置的，而是需要开发者在消费者应用中进行额外的设计。</p><h4 id="手动-ack-阻塞式重试" tabindex="-1">手动 ACK + 阻塞式重试 <a class="header-anchor" href="#手动-ack-阻塞式重试" aria-label="Permalink to &quot;手动 ACK + 阻塞式重试&quot;">​</a></h4><p>使用的方式是： Kafka 原生重试（DefaultErrorHandler）</p><p>在我们的项目中（一般指 SpringBoot 项目），我们会配置一下是否自动提交</p><p><a href="/java-site/中间件/中间件 - 消息队列/消息队列_Kafka/Kafka 重试-原生重试机制.html">Kafka 重试-原生重试机制</a></p><h4 id="组件重试" tabindex="-1">组件重试 <a class="header-anchor" href="#组件重试" aria-label="Permalink to &quot;组件重试&quot;">​</a></h4><p>项目组引入的一个组件，设计思想可以学习掌握一下</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20251118150532.png" alt="image.png"></p><h3 id="broker端" tabindex="-1">Broker端 <a class="header-anchor" href="#broker端" aria-label="Permalink to &quot;Broker端&quot;">​</a></h3><p>Kafka在内部实现了多个自动的重试机制，用于保障分布式集群的可靠性和数据一致性。</p>',13)])])}const h=e(n,[["render",i]]);export{c as __pageData,h as default};
